	{ id: "workbench", name: "AMX workbench" },
	{ id: "data", name: "Data editor" },
	{ id: "inputs", name: "Inputs" },
	{ id: "settings", name: "Report settings" },
	{ id: "export", name: "Export" },
	{ id: "runtime", name: "Runtime drawer" },
	{ id: "recovery", name: "Conflict / recovery" },
	{ id: "trash", name: "Project trash" }
] as const;

const states = ["empty", "loading", "running", "paused", "stale", "error", "success", "conflict", "recovery", "cancelled"] as const;
const stateCopy: Record<(typeof states)[number], { title: string; body: string }> = {
	empty: { title: "Ready for a document", body: "Open a project file to begin." },
	loading: { title: "Loading project", body: "Reading contained project files. Cancel leaves the current project unchanged." },
	running: { title: "Analysis in progress", body: "This result belongs to the active document revision." },
	paused: { title: "Preview paused", body: "Changes are saved, but preview refresh is paused." },
	stale: { title: "Preview is stale", body: "The last good preview is retained and is not current." },
	error: { title: "Input validation failed", body: "Review the source-linked diagnostic; no output was written." },
	success: { title: "Saved revision 18", body: "The active document and its dependencies were validated." },
	conflict: { title: "File changed on disk", body: "Compare, reload, discard, or keep editing. No overwrite occurred." },
	recovery: { title: "Recovery available", body: "Inspect the local snapshot before restoring it." },
	cancelled: { title: "Job cancelled", body: "The prior destination and active source remain unchanged." }
};

const screen = ref<(typeof screens)[number]["id"]>("workbench");
const theme = ref<"light" | "dark">("light");
const viewport = ref<"compact" | "wide">("compact");
const state = ref<(typeof states)[number]>("success");
const query = ref("");
const invoker = ref<HTMLElement | null>(null);
const helpOpen = ref(false);
const focusMode = ref(false);
const currentScreen = computed(() => screens.find(item => item.id === screen.value)!);
const currentState = computed(() => stateCopy[state.value]);
const artboardStyle = computed(() => ({
	"--frame-width": viewport.value === "compact" ? "1024px" : "1440px",
	"--frame-height": viewport.value === "compact" ? "720px" : "900px"
}));
const rows = [
	{ id: "TX-014", class: "Power transformer", score: "18.4", status: "Review" },
	{ id: "TX-021", class: "Power transformer", score: "12.7", status: "Ready" },
	{ id: "SW-006", class: "Switchgear", score: "9.8", status: "Ready" },
	{ id: "CB-031", class: "Circuit breaker", score: "8.1", status: "Review" },
	{ id: "TX-044", class: "Power transformer", score: "6.2", status: "Ready" }
];
const visibleRows = computed(() => rows.filter(row => `${row.id} ${row.class} ${row.status}`.toLowerCase().includes(query.value.toLowerCase())));

function openHelp(event: MouseEvent) {
	invoker.value = event.currentTarget as HTMLElement;
	helpOpen.value = true;
}
function closeTransient() {
	if (helpOpen.value) {
		helpOpen.value = false;
		requestAnimationFrame(() => invoker.value?.focus());
	} else if (focusMode.value) {
		focusMode.value = false;
		requestAnimationFrame(() => invoker.value?.focus());
	}
}
function onKeydown(event: KeyboardEvent) {
	if (event.key === "Escape") closeTransient();
}
function enterFocus(event: MouseEvent) {
	invoker.value = event.currentTarget as HTMLElement;
	focusMode.value = true;
}
onMounted(() => window.addEventListener("keydown", onKeydown));
onUnmounted(() => window.removeEventListener("keydown", onKeydown));
</script>

